  <script type="module">
    import * as THREE from "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // -------------------------------------------------------------------------
    // Renderer, scene, camera, and custom camera controls
    // -------------------------------------------------------------------------

    const sceneHost = document.getElementById("scene");
    const loading = document.getElementById("loading");

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.8));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    renderer.domElement.setAttribute("aria-label", "Interactive three-dimensional cliff dwelling");
    sceneHost.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x91a9b8);
    scene.fog = new THREE.Fog(0x91a9b8, 27, 68);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.1,
      120
    );

    const cameraState = {
      target: new THREE.Vector3(0, 3.0, 1.4),
      radius: 22,
      theta: 0.56,
      phi: 1.13
    };

    const desiredCamera = {
      target: cameraState.target.clone(),
      radius: cameraState.radius,
      theta: cameraState.theta,
      phi: cameraState.phi
    };

    const currentCamera = {
      target: cameraState.target.clone(),
      radius: cameraState.radius,
      theta: cameraState.theta,
      phi: cameraState.phi
    };

    function updateCamera(dt) {
      const damping = 1 - Math.exp(-8 * dt);

      currentCamera.target.lerp(desiredCamera.target, damping);
      currentCamera.radius = THREE.MathUtils.lerp(
        currentCamera.radius,
        desiredCamera.radius,
        damping
      );
      currentCamera.theta = THREE.MathUtils.lerp(
        currentCamera.theta,
        desiredCamera.theta,
        damping
      );
      currentCamera.phi = THREE.MathUtils.lerp(
        currentCamera.phi,
        desiredCamera.phi,
        damping
      );

      const sinPhi = Math.sin(currentCamera.phi);

      camera.position.set(
        currentCamera.target.x +
          currentCamera.radius * sinPhi * Math.sin(currentCamera.theta),
        currentCamera.target.y + currentCamera.radius * Math.cos(currentCamera.phi),
        currentCamera.target.z +
          currentCamera.radius * sinPhi * Math.cos(currentCamera.theta)
      );

      camera.lookAt(currentCamera.target);
    }

    function resetView() {
      desiredCamera.target.set(0, 3.0, 1.4);
      desiredCamera.radius = 22;
      desiredCamera.theta = 0.56;
      desiredCamera.phi = 1.13;
    }

    let dragging = false;
    let panning = false;
    let lastX = 0;
    let lastY = 0;

    const canvas = renderer.domElement;

    canvas.addEventListener("pointerdown", (event) => {
      dragging = true;
      panning = event.shiftKey || event.button === 2;
      lastX = event.clientX;
      lastY = event.clientY;
      canvas.setPointerCapture(event.pointerId);
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!dragging) return;

      const dx = event.clientX - lastX;
      const dy = event.clientY - lastY;
      lastX = event.clientX;
      lastY = event.clientY;

      if (panning) {
        const right = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 0);
        const up = new THREE.Vector3().setFromMatrixColumn(camera.matrix, 1);
        const scale = currentCamera.radius * 0.00135;

        desiredCamera.target
          .addScaledVector(right, -dx * scale)
          .addScaledVector(up, dy * scale);

        desiredCamera.target.x = THREE.MathUtils.clamp(
          desiredCamera.target.x,
          -11,
          11
        );
        desiredCamera.target.y = THREE.MathUtils.clamp(
          desiredCamera.target.y,
          0.5,
          10
        );
        desiredCamera.target.z = THREE.MathUtils.clamp(
          desiredCamera.target.z,
          -4,
          10
        );
      } else {
        desiredCamera.theta -= dx * 0.005;
        desiredCamera.phi = THREE.MathUtils.clamp(
          desiredCamera.phi - dy * 0.005,
          0.28,
          1.48
        );
      }
    });

    function stopDragging(event) {
      dragging = false;
      if (canvas.hasPointerCapture(event.pointerId)) {
        canvas.releasePointerCapture(event.pointerId);
      }
    }

    canvas.addEventListener("pointerup", stopDragging);
    canvas.addEventListener("pointercancel", stopDragging);
    canvas.addEventListener("contextmenu", (event) => event.preventDefault());

    canvas.addEventListener("wheel", (event) => {
      event.preventDefault();
      desiredCamera.radius = THREE.MathUtils.clamp(
        desiredCamera.radius * Math.exp(event.deltaY * 0.001),
        10,
        35
      );
    }, { passive: false });

    canvas.addEventListener("dblclick", resetView);

    // -------------------------------------------------------------------------
    // Procedural textures and materials
    // -------------------------------------------------------------------------

    function mulberry32(seed) {
      return function () {
        let t = seed += 0x6D2B79F5;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
      };
    }

    function makeWoodTexture() {
      const c = document.createElement("canvas");
      c.width = c.height = 256;
      const ctx = c.getContext("2d");
      const random = mulberry32(0x51f3);

      ctx.fillStyle = "#755035";
      ctx.fillRect(0, 0, 256, 256);

      for (let i = 0; i < 95; i++) {
        const x = random() * 256;
        const phase = random() * Math.PI * 2;

        ctx.strokeStyle = `rgba(39, 22, 11, ${0.08 + random() * 0.22})`;
        ctx.lineWidth = 0.5 + random() * 1.8;
        ctx.beginPath();

        for (let y = 0; y <= 256; y += 16) {
          ctx.lineTo(
            x + Math.sin(y * 0.085 + phase) * (1 + random() * 2.5),
            y
          );
        }

        ctx.stroke();
      }

      for (let i = 0; i < 8; i++) {
        const x = random() * 256;
        const y = random() * 256;
        const radius = 3 + random() * 8;

        ctx.strokeStyle = "rgba(40, 23, 12, 0.2)";
        ctx.lineWidth = 1.2;
        ctx.beginPath();
        ctx.ellipse(x, y, radius, radius * 0.48, 0, 0, Math.PI * 2);
